import logging
import time

import boto3
from app.config import settings
from boto3.dynamodb.conditions import Attr
from botocore.exceptions import ClientError

logger = logging.getLogger(__name__)
PARTITION_KEY = "idempotency_key"


def _get_resource():
    return boto3.resource(
        "dynamodb",
        region_name=settings.AWS_DEFAULT_REGION,
        endpoint_url=settings.DYNAMODB_ENDPOINT_URL,
    )


def _get_table():
    return _get_resource().Table(settings.DYNAMODB_TABLE_NAME)


def ensure_table_exists():
    """Verify the Terraform-managed table exists and has the expected key."""
    client = boto3.client(
        "dynamodb",
        region_name=settings.AWS_DEFAULT_REGION,
        endpoint_url=settings.DYNAMODB_ENDPOINT_URL,
    )
    try:
        response = client.describe_table(TableName=settings.DYNAMODB_TABLE_NAME)
    except ClientError:
        logger.exception("Could not verify DynamoDB table %s", settings.DYNAMODB_TABLE_NAME)
        raise

    key_schema = {
        item["AttributeName"]: item["KeyType"]
        for item in response["Table"]["KeySchema"]
    }
    if key_schema.get(PARTITION_KEY) != "HASH":
        raise RuntimeError(
            f"Table {settings.DYNAMODB_TABLE_NAME} must use "
            f"{PARTITION_KEY!r} as its HASH key; found {key_schema}"
        )

    logger.info("DynamoDB table %s is ready.", settings.DYNAMODB_TABLE_NAME)


def insert_if_absent(record: dict) -> bool:
    """Atomically insert a new record; return False if the key already exists."""
    if PARTITION_KEY not in record:
        raise ValueError(f"Record must include {PARTITION_KEY!r}")

    table = _get_table()
    record["expiresAt"] = int(time.time()) + settings.IDEMPOTENCY_TTL_HOURS * 3600
    try:
        table.put_item(
            Item=record,
            ConditionExpression=f"attribute_not_exists({PARTITION_KEY})",
        )
        logger.info("Insert success key=%s", record[PARTITION_KEY])
        return True
    except ClientError as error:
        if error.response["Error"]["Code"] == "ConditionalCheckFailedException":
            logger.info("Duplicate detected key=%s", record[PARTITION_KEY])
            return False
        logger.exception("Insert error")
        raise


def find_by_key(idempotency_key: str) -> dict | None:
    """Strongly consistent point read."""
    response = _get_table().get_item(
        Key={PARTITION_KEY: idempotency_key},
        ConsistentRead=True,
    )
    return response.get("Item")


def complete(idempotency_key: str, final_status: str, response_payload: str | None):
    """Update only a record currently in PROCESSING status."""
    try:
        _get_table().update_item(
            Key={PARTITION_KEY: idempotency_key},
            UpdateExpression="SET #st = :status, responsePayload = :payload, updatedAt = :ts",
            ConditionExpression=Attr("status").eq("PROCESSING"),
            ExpressionAttributeNames={"#st": "status"},
            ExpressionAttributeValues={
                ":status": final_status,
                ":payload": response_payload or "",
                ":ts": int(time.time() * 1000),
            },
        )
        logger.info("Complete success key=%s status=%s", idempotency_key, final_status)
    except ClientError as error:
        if error.response["Error"]["Code"] == "ConditionalCheckFailedException":
            logger.warning("Complete skipped — not PROCESSING key=%s", idempotency_key)
            return
        logger.exception("Complete error")
        raise


def scan_all() -> list:
    return _get_table().scan().get("Items", [])
